?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CRM Dashboard</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="site-header"><a class="brand" href="../index.html"><span class="brand-mark">W</span><span>Web<span>Studio</span></span></a><nav class="nav"><a href="../index.html">Website</a><a href="customers.php">Customers</a><a href="quotes.php">Quotes</a><a href="projects.php">Projects</a><a href="../quote.html">New Quote</a><a href="logout.php" class="btn btn-sm btn-3d">Log out</a></nav></header><main><section class="section"><span class="eyebrow">INTERNAL CRM</span><h1 style="font-size:clamp(2.7rem,5vw,4.5rem);line-height:1;letter-spacing:-.06em">Sales Dashboard</h1><div class="metric-grid" style="margin:30px 0"><div class="metric"><strong><?=$total?></strong><span>Total leads</span></div><div class="metric"><strong><?=$new?></strong><span>New</span></div><div class="metric"><strong><?=$quoted?></strong><span>Quoted</span></div><div class="metric"><strong><?=$won?></strong><span>Won</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Lead</th><th>Customer</th><th>Services</th><th>Country</th><th>Budget</th><th>Received</th><th>Status</th></tr></thead><tbody><?php foreach($leads as $l):$sv=json_decode($l['services'],true)?:[];?><tr><td><b><?=htmlspecialchars($l['lead_code'])?></b></td><td><?=htmlspecialchars($l['name'])?><br><span class="form-note"><?=htmlspecialchars($l['business'])?><br><?=htmlspecialchars($l['email'])?></span></td><td><?=htmlspecialchars(implode(', ',$sv))?></td><td><?=htmlspecialchars($l['country'])?></td><td><?=htmlspecialchars($l['budget'])?></td><td><?=htmlspecialchars($l['created_at'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="id" value="<?=$l['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach(['New','Contacted','Quoted','Won','Lost'] as $s):?><option <?=$l['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></form></td></tr><?php endforeach;if(!$leads):?><tr><td colspan="7">No enquiries yet.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
